def completar_juego_y_clave(apps, schema_editor):
    """Las preguntas que ya estaban cargadas reciben su juego y su clave, así
    cargar_datos las actualiza en vez de duplicarlas."""
    Pregunta = apps.get_model("actividades", "Pregunta")
    for pregunta in Pregunta.objects.all():
        if pregunta.tipo == "memoria":
            pregunta.juego = "asociacion"
        elif pregunta.tipo == "atencion" and pregunta.enunciado == "Encuentra el mismo dibujo":
            pregunta.juego = "pareja_igual"
        else:
            pregunta.juego = "eleccion"
        try:
            pregunta.clave = pregunta.opciones[pregunta.respuesta_correcta]["texto"][:80]
        except (IndexError, KeyError, TypeError):
            pregunta.clave = ""
        pregunta.save(update_fields=["juego", "clave"])


